/* =====================================================================
   106-V75 · v0.75 — fixes and the next batch
   =====================================================================
   • The ratings fold above the avatar answers on the PRESS (pointerdown). The fighter board is rebuilt many times a second
     during turns; a click needs press + release on the same button, so a rebuild in between swallowed it. Keyboard
     (Enter/Space → click with detail 0) still uses the click path; the click that follows a press is ignored.
   • His weapon-card icons (rulebook p.10; tools/art/icons/strip9.webp → wico_sheet.png): both attacks, soul steal, attack power,
     use, range, crowd favor, throw, ammo, shield absorb — embedded as data URIs (custom cards are SVGs drawn into <img>s,
     which cannot load files) and drawn in place of the v0.42 vector icons on custom weapon cards and the Weapon forge tiles.
   • His Ornate Chest Armor (armor2.webp cell 44; L2 chest 4 AP, `ornate`) = the Royalty's starting chest (the Scaled Chest Armor
     stays in the market; the Ornate one is sold too). Flavius' Greaves wear his single greave (cell 43) on the avatar, mirrored on the
     left; the card/thumbnail keeps the pair (cell 24).
   • Tokens: the 3D minis replace the standees (Virgilante) — the Standees row leaves Settings → Tokens, a standee choice always
     wears the minis (applySettings wrapper keeps SETTINGS.mini3d on; old standee players switched once). Pieces with no mini
     (custom beasts) keep their flat standee art. The pillar mini is 15% shorter and wears his pillar standee's painted stone
     (assets/mini_pillar.webp re-rendered by tools/art/minis/render3.html + shot3.js from pillar_tex.png).
   ===================================================================== */
document.addEventListener('pointerdown',e=>{if(e.button!==0)return;const t=e.target.closest&&e.target.closest('.ratfold');if(!t)return;e.preventDefault();
  RAT_SHUT=!RAT_SHUT;try{localStorage.setItem('flavius_ratshut',RAT_SHUT?'1':'0')}catch(err){}panelStatsUp()},true);
document.addEventListener('click',e=>{if(!e.target.closest||!e.target.closest('.ratfold'))return;if(e.detail===0)return;
  e.stopImmediatePropagation();e.preventDefault()},true); /* a pointer click: the press already toggled */

/* ---------- his weapon-card icons ---------- */
const WICO75={"both":"data:image/webp;base64,","soul":"data:image/webp;base64,","dmg":"data:image/webp;base64,","use":"data:image/webp;base64,","rng":"data:image/webp;base64,","cf":"data:image/webp;base64,","thr":"data:image/webp;base64,","ammo":"data:image/webp;base64,","abs":"data:image/webp;base64,"};
for(const k of Object.keys(WICO75))CW_ICO[k]=(c,h=12)=>`<image href="${WICO75[k]}" x="${-h}" y="${-h}" width="${2*h}" height="${2*h}"/>`;
CW_ICO.brk=CW_ICO.use;
cwIcoSVG=function(k,px=26){return `<svg viewBox="-9 -9 18 18" width="${px}" height="${px}" aria-hidden="true">${(CW_ICO[k]||CW_ICO.dmg)(null,9)}</svg>`};
/* the fighter board's weapon rows: his icons with the numbers instead of "P1 · R1 · ammo 3" */
function wStatsIco75(w){if(!w||w.lyre||w.noAtk)return null;const I=(k,v,t)=>`<span class="wi75" title="${esc(t)}"><img src="${WICO75[k]}" alt="">${v}</span>`;const o=[];
  if(w.shield&&!w.p){o.push(I('abs',w.absorb,'Shield absorb'),I('use',w.usesLeft,'Uses left'));return o.join('')+'<span class="wi75 no">no attack</span>'}
  o.push(I('dmg',w.p,'Attack power'),I('rng',w.r,'Range'));if(w.ammo!=null)o.push(I('ammo',w.ammoLeft,'Ammo'));if(w.shield)o.push(I('abs',w.absorb,'Shield absorb'),I('use',w.usesLeft,'Uses left'));
  if(w.throw)o.push(I('thr',`P${w.throw.p} R${w.throw.r} ×${w.throwsLeft}`,'Throw: power, range, throws left'));if(w.atkUses)o.push(I('use',w.atkLeft,'Uses left'));if(w.both)o.push(I('both','','Both attacks'));
  if(w.soul)o.push(I('soul',w.soul,'Soul steal'));if(w.cfw)o.push(I('cf','+'+w.cfw,'Crowd favor per hit'));return o.join('')}
{const base=boardHTML;boardHTML=function(player){let h=base.apply(this,arguments);try{if(player)for(const a of ['R','L']){const w=player['w'+a];const ic=wStatsIco75(w);if(!ic)continue;
  const t=`<span class="ws">${wStats(w)}`;const i=h.indexOf(t);if(i>=0)h=h.slice(0,i)+`<span class="ws ws75">${ic}`+h.slice(i+t.length)}}catch(e){console.error(e)}return h}}
(()=>{const st=document.createElement('style');st.textContent=`.ws75{display:inline-flex;flex-wrap:wrap;gap:2px 7px;justify-content:flex-end;align-items:center}
.wi75{display:inline-flex;align-items:center;gap:2px;font:600 12px var(--mono);color:var(--bone);white-space:nowrap}.wi75 img{width:20px;height:20px;display:block}.wi75.no{font-weight:400;color:var(--muted)}`;document.head.appendChild(st)})();

/* ---------- his Ornate Chest Armor + the single Flavius' Greave ---------- */
ARM_CROP[43]=[2419,1335,112,300];ARM_CROP[44]=[2713,1335,184,300];
ARM.ornate={n:'Ornate Chest Armor',lv:2,slot:'chest',pt:'chest',ap:4,img:44};ARM_FIT.ornate={at:'chest',dy:5,w:59};
if(!MARKET_A[2].includes('ornate'))MARKET_A[2].push('ornate');
if(CLASSES.royalty)CLASSES.royalty.armor=CLASSES.royalty.armor.map(([k,l])=>[k==='lorica'?'ornate':k,l]);
if(ARM.greaves){ARM.greaves.thumb=24;ARM.greaves.img=43;ARM_FIT.greaves={at:'shin',dy:-7,w:23}}

/* ---------- 3D minis instead of standees; the pillar shorter ---------- */
const MINI_PILLAR75=0.85; /* TWEAK: the pillar's height against v0.74 */
{const base=miniScale;miniScale=function(k){const s=base.apply(this,arguments);return k==='pillar'?s*MINI_PILLAR75:s}}
{const base=applySettings;applySettings=function(){try{if(SETTINGS.tokenStyle==='standee')SETTINGS.mini3d=true}catch(e){}return base.apply(this,arguments)}}
try{if(SETTINGS.tokenStyle==='standee'&&!SETTINGS.mini3d)applySettings()}catch(e){}
{const base=settingsHTML;settingsHTML=function(tab){let h=base.apply(this,arguments);if(tab!=='tokens'||typeof h!=='string')return h;
  return h.replace(/<button type="button" class="tokrow[^"]*" data-tokstyle="standee">[\s\S]*?<\/button>/,'')}}
